/**
 * Nepal's eight main trekking regions, drawn with their borders on the home
 * page's hero map and used to file each trek under one of them.
 *
 * A trekking region is not an administrative unit, so each one is the union
 * of the districts its trails run through:
 *
 *   Annapurna     Kaski, Manang, Myagdi, Lamjung
 *   Everest       Solukhumbu
 *   Manaslu       Gorkha
 *   Langtang      Rasuwa, Sindhupalchok (Langtang, Gosaikunda, Helambu)
 *   Makalu        Sankhuwasabha
 *   Dolpo         Dolpa
 *   Kanchenjunga  Taplejung
 *   Mustang       Mustang
 *
 * Source: the Survey Department's 77-district boundaries (2017 federal
 * structure, OCHA P-codes), via github.com/mesaugat/geoJSON-Nepal (MIT).
 * Districts were dissolved per region and simplified with mapshaper
 * (`-dissolve region -simplify interval=200 keep-shapes`), then rounded to 4
 * decimals: under a pixel at the zooms the borders are drawn at, and ~3,600
 * points for all eight instead of the source's 14 MB. Label points are
 * mapshaper's `-points inner`, a spot well inside each shape.
 */

export type TrekRegionSlug =
  | "annapurna"
  | "everest"
  | "manaslu"
  | "langtang"
  | "makalu"
  | "dolpo"
  | "kanchenjunga"
  | "mustang";

type Ring = Array<[number, number]>;

interface RegionShape {
  /** [[west, south], [east, north]] */
  bounds: [[number, number], [number, number]];
  /** Where the region's name is drawn, [lng, lat]. */
  label: [number, number];
  /** Outer ring, [lng, lat], closed. */
  ring: Ring;
}

