export interface TrekRegion extends RegionShape {
  slug: TrekRegionSlug;
  /** As the CMS writes it in Trek.region, e.g. "Annapurna Region". */
  name: string;
  /** Short map label, e.g. "Annapurna". */
  short: string;
  /** Fill and border colour. Neighbouring regions get clearly different hues. */
  color: string;
}

const META: Array<Pick<TrekRegion, "slug" | "name" | "short" | "color">> = [
  { slug: "annapurna", name: "Annapurna Region", short: "Annapurna", color: "#00e198" },
  { slug: "everest", name: "Everest Region", short: "Everest", color: "#38bdf8" },
  { slug: "manaslu", name: "Manaslu Region", short: "Manaslu", color: "#facc15" },
  { slug: "langtang", name: "Langtang Region", short: "Langtang", color: "#f472b6" },
  { slug: "makalu", name: "Makalu Region", short: "Makalu", color: "#fb923c" },
  { slug: "dolpo", name: "Dolpo Region", short: "Dolpo", color: "#fb7185" },
  { slug: "kanchenjunga", name: "Kanchenjunga Region", short: "Kanchenjunga", color: "#a3e635" },
  { slug: "mustang", name: "Mustang Region", short: "Mustang", color: "#c084fc" },
];

export const TREK_REGIONS: TrekRegion[] = META.map((meta) => ({ ...meta, ...SHAPES[meta.slug] }));

export const TREK_REGION_BY_SLUG = Object.fromEntries(TREK_REGIONS.map((r) => [r.slug, r])) as Record<
  TrekRegionSlug,
  TrekRegion
>;

/** The regions as polygons, keyed by `slug` (use it as the source's promoteId). */
export const TREK_REGIONS_GEOJSON = {
  type: "FeatureCollection" as const,
  features: TREK_REGIONS.map((r) => ({
    type: "Feature" as const,
    properties: { slug: r.slug, name: r.name, short: r.short, color: r.color },
    geometry: { type: "Polygon" as const, coordinates: [r.ring] },
  })),
};

/**
 * The region a CMS region name refers to ("Annapurna Region", "everest",
 * "Kangchenjunga Region"), or null for anything else ("Remote Region").
 */
export function regionSlugForName(name: string | null | undefined): TrekRegionSlug | null {
  const key = (name ?? "").toLowerCase().replace(/region/g, "").replace(/[^a-z]/g, "");
  if (!key) return null;
  if (key === "kangchenjunga") return "kanchenjunga";
  return (TREK_REGIONS.find((r) => r.slug === key)?.slug ?? null) as TrekRegionSlug | null;
}

/** Even–odd ray cast; the rings are simple polygons. */
function inRing(lng: number, lat: number, ring: Ring): boolean {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if (yi > lat !== yj > lat && lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

/** The region a point lies in, or null outside all eight. */
export function regionAt(lng: number, lat: number): TrekRegionSlug | null {
  for (const r of TREK_REGIONS) {
    const [[w, s], [e, n]] = r.bounds;
    if (lng >= w && lng <= e && lat >= s && lat <= n && inRing(lng, lat, r.ring)) return r.slug;
  }
  return null;
}
